import functools

_UNHASHABLE = object()


def _freeze(value):
    """Recursively make a value hashable, marking unhashable parts."""
    try:
        hash(value)
    except TypeError:
        if isinstance(value, dict):
            items = tuple(sorted((_freeze(k), _freeze(v)) for k, v in value.items()))
            return (dict, items)
        if isinstance(value, (list, tuple)):
            return type(value), tuple(_freeze(item) for item in value)
        if isinstance(value, set):
            return (frozenset, frozenset(_freeze(item) for item in value))
        return (type(value), id(value))
    return value


def _make_key(fn, args, kwargs):
    """Build a hashable cache key from positional and keyword arguments.

    Positional and keyword forms of the same call map to the same key, and
    keyword argument order does not matter. Returns None if the key itself
    cannot be hashed (such calls are simply not cached).
    """
    bound = list(args)
    for name, value in sorted(kwargs.items()):
        if name in bound:
            return None  # duplicate argument
        bound.append(value)
    # If any value is unhashable, fall back to per-argument identity so the
    # call is deterministic (and distinct from equal-lookalikes), not cached.
    key = tuple(_freeze(value) for value in bound)
    try:
        hash(key)
    except TypeError:
        return None
    return key


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        key = _make_key(fn, args, kwargs)
        if key is not None and key in cache:
            stats["hits"] += 1
            return cache[key]
        stats["misses"] += 1
        result = fn(*args, **kwargs)
        if key is not None:
            cache[key] = result
        return result

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper
